 ('rfq-template.csv','RFQ requirement template'),('supplier-scorecard.csv','Supplier comparison scorecard'),('supplier-audit-checklist.csv','Supplier audit checklist'),('sample-approval-sheet.csv','Sample approval sheet'),('pre-shipment-inspection-checklist.csv','Pre-shipment inspection checklist'),('packaging-specification-template.csv','Packaging specification template'),('purchase-order-checklist.csv','Purchase order checklist'),('landed-cost-calculator.csv','Landed-cost calculator')
