def e(v): return html.escape(str(v), quote=True)

def alts(page):
    d={'en':f'/{page}/'}
    for code in LOCALES: d[LANG[code]]=f'/{code}/{page}/'
    d['x-default']=f'/{page}/'
    return d

def nav(code,c):
    return f'<header class="nav-shell"><nav class="nav wrap"><a class="brand" href="/{code}/"><img src="/assets/logo.svg" alt="Pomerol International"><span>Pomerol International<small>{e(c["brand_sub"])}</small></span></a><button class="menu-btn" data-menu aria-label="Menu">☰</button><div class="navlinks" data-nav><a href="/{code}/services/">{e(c["services"])}</a><a href="/{code}/cases/">{e(c["cases"])}</a><a href="/{code}/about/">{e(c["about"])}</a><a href="/{code}/resources/">{e(c["resources"])}</a><a class="nav-cta" href="/{code}/contact/">{e(c["contact"])}</a></div></nav></header>'

def footer(code,c):
    return f'<footer class="footer"><div class="wrap"><div class="footer-grid"><div><a class="brand" href="/{code}/"><img src="/assets/logo.svg" alt=""><span>Pomerol International<small>波美猴国际贸易（珠海）有限公司</small></span></a><p style="max-width:380px;color:#aebccd">China sourcing, procurement, OEM/ODM, quality control and export coordination.</p></div><div><h4>{e(c["services"])}</h4><a href="/{code}/services/">{e(c["services"])}</a><a href="/{code}/cases/">{e(c["cases"])}</a><a href="/{code}/about/">{e(c["about"])}</a></div><div><h4>{e(c["resources"])}</h4><a href="/{code}/resources/">{e(c["resources"])}</a><a href="/{code}/resources/guides/">Buyer Guides</a><a href="/sitemap/">Site directory</a></div><div><h4>{e(c["direct"])}</h4><a href="tel:+8613242694270">+86 132 4269 4270</a><a href="mailto:abd.yusuf.ibrahim.mustafa@gmail.com">abd.yusuf.ibrahim.mustafa@gmail.com</a><a href="https://wa.me/8613242694270">WhatsApp</a></div></div><div class="footer-bottom"><span>© 2026 Pomerol International Trade (Zhuhai) Co., Ltd.</span><span><a style="display:inline" href="/privacy/">Privacy</a> · <a style="display:inline" href="/terms/">Terms</a></span></div></div></footer>'

def page(code,kind,title,desc,body,img):
    can=f'{BASE}/{code}/{kind}/'; tags=seo.seo_tags(title,desc,can,LANG[code],BASE+img,alts=alts(kind),extra=[seo.crumbs(can,title)])
    c=COPY[code]
    return f'<!doctype html><html lang="{LANG[code]}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><link rel="icon" href="/assets/logo.svg"><link rel="stylesheet" href="/assets/site.css"><script defer src="/assets/site.js"></script>{tags}</head><body>{nav(code,c)}<main>{body}</main>{footer(code,c)}</body></html>'

