def write_pages():
    made=0
    for code in LOCALES:
        c=COPY[code]
        specs=[('services',c['services_page'],services_body(code),'/assets/photos/product-development.jpg'),('about',c['about_page'],about_body(code),'/assets/photos/product-development.jpg'),('resources',c['resources_page'],resources_body(code),'/assets/photos/precision-machining.jpg'),('contact',c['contact_page'],contact_body(code),'/assets/photos/product-development.jpg')]
        for kind,d,body,img in specs:
            out=PUBLIC/code/kind; out.mkdir(parents=True,exist_ok=True); (out/'index.html').write_text(page(code,kind,d['title'],d['desc'],body,img),encoding='utf-8'); made+=1
    return made

def patch_english_clusters():
    for kind in ('services','about','resources','contact'):
        p=PUBLIC/kind/'index.html'; text=p.read_text(encoding='utf-8'); title,desc=seo.title_desc(text); text=seo.strip_seo(text); can=f'{BASE}/{kind}/'; img=seo.image_for(text); tags=seo.seo_tags(title,desc,can,'en',img,alts=alts(kind),extra=[seo.crumbs(can,title)]); text=text.replace('</head>',tags+'\n</head>',1); p.write_text(text,encoding='utf-8')

def patch_local_internal_links():
    for code in LOCALES:
        for p in (PUBLIC/code).rglob('*.html'):
            text=p.read_text(encoding='utf-8')
            for kind in ('services','about','resources','contact'):
                text=text.replace(f'href="/{kind}/"',f'href="/{code}/{kind}/"')
            p.write_text(text,encoding='utf-8')

def main():
    made=write_pages(); assert made==20,made
    patch_english_clusters(); patch_local_internal_links()
    for kind in ('services','about','resources','contact'):
        en=(PUBLIC/kind/'index.html').read_text(encoding='utf-8')
        for code in LOCALES:
            assert f'hreflang="{LANG[code]}" href="{BASE}/{code}/{kind}/"' in en,(kind,code)
            p=PUBLIC/code/kind/'index.html'; assert p.is_file(),p; t=p.read_text(encoding='utf-8'); assert 'hreflang="en"' in t and f'rel="canonical" href="{BASE}/{code}/{kind}/"' in t,p
    print('Localized deep pages OK: 20 pages + 4 reciprocal six-language hreflang clusters')

if __name__=='__main__': main()
